SELECT TOP 20  * FROM customer;
-- What is the total revenue generated by male vs female customers
SELECT
	gender,
	SUM(purchase_amount) TotalRevenue
FROM customer
GROUP BY(gender);

-- Which customer used a discount but still spent more than the avg purchase amount?
SELECT
customer_id,
purchase_amount
FROM customer
WHERE discount_applied = 'Yes' AND purchase_amount >=(SELECT AVG(purchase_amount) FROM customer);

-- Which are the top 5 products with high average review rating
SELECT TOP 5
	item_purchased,
	ROUND(AVG(review_rating) ,2) AS AvgRating
FROM customer
GROUP BY item_purchased
ORDER BY AVG(review_rating) DESC;

-- Compare the average purchase amounts between standard and express shipping
 SELECT
	 shipping_type,
	 ROUND(AVG(purchase_amount),2) AvgPurchaseAmount
 FROM customer
 WHERE shipping_type in ('Standard','Express')
 GROUP BY shipping_type;

 --Do subscribed customers spend more? Compare avg spend and total revenue between subscribers and non-subscribers
 SELECT
	 subscription_status,
	 COUNT(customer_id) AS TotalCustomer,
	 ROUND(AVG(purchase_amount),2) AS AvgSpend,
	 ROUND(SUM(purchase_amount),2) AS TotalRevenue
 FROM customer
 GROUP BY subscription_Status
 ORDER BY TotalRevenue, AvgSpend DESC;

 -- Which 5 products have the highest percentage of purchase with discount applied?
 SELECT TOP 5
	 item_purchased,
	 ROUND(100*SUM(CASE WHEN discount_applied = 'Yes' THEN 1 ELSE 0 END)/COUNT(*), 2) AS DiscountRate
 FROM customer
 GROUP BY item_purchased
 ORDER BY DiscountRate DESC;

 -- Segment customers into New, Returning and loyal based on their total number of previous purchases and show the count of each segment
 WITH CustomerType AS
 (
	SELECT 
		customer_id,
		previous_purchases,
		CASE
			WHEN previous_purchases = 1 THEN 'New'
			WHEN previous_purchases BETWEEN 2 AND 10 THEN 'Returning'
			ELSE 'Loyal'
		END AS CustomerSegment
	FROM customer
)
SELECT 
	CustomerSegment,
	COUNT(*) AS TotalCustomer
FROM CustomerType
GROUP BY CustomerSegment;

-- What are the top 3 most purchased produts within each category
WITH ItemCounts AS
(
	SELECT 
		category,
		item_purchased,
		COUNT(customer_id) AS TotalOrders,
		ROW_NUMBER() OVER(PARTITION BY category ORDER BY COUNT(customer_id) DESC) AS item_rank
	FROM customer
	GROUP BY category, item_purchased
)
SELECT
	item_rank,
	category,
	item_purchased,
	TotalOrders
FROM ItemCounts
WHERE item_rank <= 3;

-- Are customer who are repeat buyers (more than 5 previous purchases) also likely to subscribe?
SELECT 
	subscription_Status,
	COUNT(customer_id) as RepeatBuyers
FROM customer
WHERE previous_purchases > 5
GROUP BY subscription_status;

-- What is the revenue contributions of each age group
SELECT
age_group,
SUM(purchase_amount) AS TotalRevenue
FROM customer
GROUP BY age_group
ORDER BY TotalRevenue DESC;